package com.gameaggregator.clientservice.domain;import jakarta.persistence.*;import java.util.UUID;@Entity @Table(name="client_applications") public class ClientApplication{@Id public UUID id=UUID.randomUUID();@Column(nullable=false)public UUID organizationId;@Column(nullable=false)public String name;@Column(nullable=false,unique=true)public String clientKey=UUID.randomUUID().toString();@Column(nullable=false)public String integrationStatus="PENDING";protected ClientApplication(){}public ClientApplication(UUID o,String n){organizationId=o;name=n;}}
